package com.medtrack.auth.service; import com.medtrack.auth.dto.*; import com.medtrack.auth.entity.RefreshToken; import com.medtrack.auth.repository.RefreshTokenRepository; import com.medtrack.auth.security.*; import com.medtrack.shared.exception.DomainException; import com.medtrack.user.entity.*; import com.medtrack.user.repository.UserRepository; import java.security.SecureRandom; import java.time.Instant; import java.util.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class AuthService {private final UserRepository users;private final RefreshTokenRepository tokens;private final PasswordEncoder encoder;private final JwtService jwt;private final JwtProperties props;private final SecureRandom random=new SecureRandom();public AuthService(UserRepository u,RefreshTokenRepository t,PasswordEncoder e,JwtService j,JwtProperties p){users=u;tokens=t;encoder=e;jwt=j;props=p;}public AuthResult login(LoginRequest r){User u=users.findByEmailIgnoreCase(r.email()).orElseThrow(()->new DomainException("INVALID_CREDENTIALS","Invalid email or password"));if(u.getStatus()!=UserStatus.ACTIVE||!encoder.matches(r.password(),u.getPasswordHash()))throw new DomainException("INVALID_CREDENTIALS","Invalid email or password");return issue(u,UUID.randomUUID());}public AuthResult refresh(String value){RefreshToken old=tokens.findByTokenHash(hash(value)).orElseThrow(()->new DomainException("INVALID_REFRESH_TOKEN","Refresh token is invalid"));if(old.getRevokedAt()!=null){old.markReuseDetected();tokens.findByFamilyId(old.getFamilyId()).forEach(t->t.revoke(Instant.now()));throw new DomainException("REFRESH_TOKEN_REUSE_DETECTED","Refresh token reuse detected; token family revoked");}if(old.getExpiresAt().isBefore(Instant.now()))throw new DomainException("REFRESH_TOKEN_EXPIRED","Refresh token has expired");old.revoke(Instant.now());return issue(old.getUser(),old.getFamilyId());}public void logout(String value){tokens.findByTokenHash(hash(value)).ifPresent(t->t.revoke(Instant.now()));}private AuthResult issue(User u,UUID family){String raw=randomToken();tokens.save(new RefreshToken(u,hash(raw),family,Instant.now().plusSeconds(props.refreshTokenDays()*86400)));return new AuthResult(new AuthResponse(jwt.issue(u),"Bearer",jwt.expiry(),u.getEmail(),u.getRole().getName()),raw);}private String randomToken(){byte[]b=new byte[48];random.nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}private String hash(String raw){try{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(raw.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}public record AuthResult(AuthResponse response,String refreshToken){}}
